(function(){var sf=document.getElementById('starfield');for(var i=0;i<130;i++){var s=document.createElement('div');s.className='star';var sz=Math.random()*2+0.4;s.style.cssText='width:'+sz+'px;height:'+sz+'px;left:'+Math.random()*100+'%;top:'+Math.random()*100+'%;--dur:'+(2+Math.random()*5)+'s;--delay:'+(Math.random()*6)+'s;--lo:'+(0.05+Math.random()*0.15)+';--hi:'+(0.4+Math.random()*0.55);sf.appendChild(s);}var cv=document.getElementById('meteors');if(cv){var ctx=cv.getContext('2d');function rsz(){cv.width=innerWidth;cv.height=innerHeight;}rsz();window.addEventListener('resize',rsz);function Meteor(init){this.reset(init);}Meteor.prototype.reset=function(init){this.x=Math.random()*innerWidth*1.4-innerWidth*0.2;this.y=init?Math.random()*-innerHeight:-80;this.len=90+Math.random()*130;this.spd=1.6+Math.random()*2.2;this.ang=Math.PI/4+(Math.random()-0.5)*0.25;this.w=0.4+Math.random()*0.9;this.life=0;this.maxLife=70+Math.random()*110;this.peak=0.25+Math.random()*0.4;};Meteor.prototype.draw=function(){this.life++;var fi=18,fo=22,a;if(this.life<fi){a=(this.life/fi)*this.peak;}else if(this.life>this.maxLife-fo){a=((this.maxLife-this.life)/fo)*this.peak;}else{a=this.peak;}if(this.life>=this.maxLife)this.reset();var tx=this.x-Math.cos(this.ang)*this.len;var ty=this.y-Math.sin(this.ang)*this.len;this.x+=Math.cos(this.ang)*this.spd;this.y+=Math.sin(this.ang)*this.spd;var g=ctx.createLinearGradient(tx,ty,this.x,this.y);g.addColorStop(0,'transparent');g.addColorStop(1,'rgba(201,168,76,'+a+')');ctx.beginPath();ctx.moveTo(tx,ty);ctx.lineTo(this.x,this.y);ctx.strokeStyle=g;ctx.lineWidth=this.w;ctx.stroke();};var meteors=[];var animPaused=false;var animFrame=null;for(var i=0;i<10;i++)meteors.push(new Meteor(true));function animLoop(){if(animPaused)return;ctx.clearRect(0,0,cv.width,cv.height);for(var i=0;i<meteors.length;i++)meteors[i].draw();animFrame=requestAnimationFrame(animLoop);}animLoop();document.addEventListener('visibilitychange',function(){if(document.hidden){animPaused=true;if(animFrame)cancelAnimationFrame(animFrame);}else{animPaused=false;animLoop();}});}var fades=document.querySelectorAll('.fade');var observer=new IntersectionObserver(function(entries){entries.forEach(function(e){if(e.isIntersecting){e.target.classList.add('show');}});},{threshold:0.08});fades.forEach(function(el){observer.observe(el);});var st=document.getElementById('scroll-top');if(st){window.addEventListener('scroll',function(){st.classList.toggle('visible',window.scrollY>400);});}window.toggleMob=function(){var menu=document.getElementById('mob-menu');var ham=document.getElementById('ham');menu.classList.toggle('open');ham.classList.toggle('open');};window.closeMob=function(){document.getElementById('mob-menu').classList.remove('open');document.getElementById('ham').classList.remove('open');};window.toggleBuls=function(id,btn){var buls=document.getElementById(id);var more=btn.dataset.more;var less=btn.dataset.less;var hidden=buls.querySelectorAll('.exp-bul-hidden');var isOpen=btn.classList.contains('open');if(isOpen){hidden.forEach(function(b){b.classList.add('exp-bul-hidden');});btn.classList.remove('open');btn.textContent=more;}else{hidden.forEach(function(b){b.classList.remove('exp-bul-hidden');});btn.classList.add('open');btn.textContent=less;}};window.toggleChips=function(id,btn){var chips=document.getElementById(id);var hidden=chips.querySelectorAll('.exp-chip-hidden');var isOpen=btn.classList.contains('open');if(isOpen){hidden.forEach(function(c){c.classList.add('exp-chip-hidden');});btn.classList.remove('open');btn.textContent='+'+hidden.length+' more';}else{hidden.forEach(function(c){c.classList.remove('exp-chip-hidden');});btn.classList.add('open');btn.textContent='Show less';}};window.toggleAllCerts=function(btn){var all=document.getElementById('cert-groups-all');var isOpen=all.style.display==='block';all.style.display=isOpen?'none':'block';btn.textContent=isOpen?'View all certifications':'Show fewer';};window.toggleCert=function(group){var isOpen=group.classList.contains('open');group.classList.toggle('open');var header=group.querySelector('.cert-group-header');if(header){header.setAttribute('aria-expanded',!isOpen);}};window.rotateFun=function(){var funBtn=document.getElementById('fun-btn');var funText=document.getElementById('fun-text');var facts=['I have a spreadsheet that has been open for 3+ years','I once automated a 45-minute process down to 5 minutes','My cats have stronger opinions than most executives','I build systems that survive my absence','I find joy in a perfectly structured spreadsheet','I once reduced batch processing time by 89%','I believe every process should be documented','I can talk about SAP integrations for hours','I collect certifications like some collect stamps','I think in workflows and systems'];var randomFact=facts[Math.floor(Math.random()*facts.length)];funText.textContent=randomFact;funText.style.opacity='0';funText.style.transform='translateY(-10px)';setTimeout(function(){funText.style.opacity='1';funText.style.transform='translateY(0)';},100);};window.openModal=function(){document.getElementById('contact-modal').style.display='flex';document.body.style.overflow='hidden';};window.closeModal=function(){document.getElementById('contact-modal').style.display='none';document.body.style.overflow='';};window.handleModalClick=function(e){if(e.target.id==='contact-modal'){closeModal();}};document.addEventListener('keydown',function(e){if(e.key==='Escape'){closeModal();}});document.getElementById('contact-form').addEventListener('submit',function(e){e.preventDefault();var formData=new FormData(this);var submitBtn=this.querySelector('.form-submit');var originalText=submitBtn.textContent;submitBtn.textContent='Sending...';submitBtn.disabled=true;fetch('https://formspree.io/f/xvzwovee',{method:'POST',body:formData,headers:{'Accept':'application/json'}}).then(function(response){if(response.ok){submitBtn.textContent='Message sent!';submitBtn.style.background='#4ade80';setTimeout(function(){closeModal();submitBtn.textContent=originalText;submitBtn.style.background='';submitBtn.disabled=false;document.getElementById('contact-form').reset();},2000);}else{throw new Error('Form submission failed');}}).catch(function(error){submitBtn.textContent='Send Message';submitBtn.disabled=false;alert('Sorry, there was an error sending your message. Please try again.');});});var navLinks=document.querySelectorAll('.nav-links a');var currentPath=window.location.pathname;navLinks.forEach(function(link){var href=link.getAttribute('href');if(href===currentPath||(href==='/'&&currentPath==='/')){link.classList.add('nav-active');}});var dropdownBtn=document.querySelector('.nav-dropdown-btn');var dropdownMenu=document.querySelector('.nav-dropdown-menu');if(dropdownBtn&&dropdownMenu){dropdownBtn.addEventListener('click',function(){var isOpen=dropdownBtn.getAttribute('aria-expanded')==='true';dropdownBtn.setAttribute('aria-expanded',!isOpen);dropdownMenu.style.display=isOpen?'none':'block';});document.addEventListener('click',function(e){if(!dropdownBtn.contains(e.target)&&!dropdownMenu.contains(e.target)){dropdownMenu.style.display='none';dropdownBtn.setAttribute('aria-expanded','false');}});}document.querySelectorAll('a[href^="#"]').forEach(function(anchor){anchor.addEventListener('click',function(e){e.preventDefault();var targetId=this.getAttribute('href').substring(1);var targetElement=document.getElementById(targetId);if(targetElement){var navHeight=document.querySelector('nav').offsetHeight;var targetPosition=targetElement.offsetTop-navHeight-20;window.scrollTo({top:targetPosition,behavior:'smooth'});}});});});
